from functools import lru_cache
wins = [c for c in __import__('itertools').combinations(range(1,10),3) if sum(c)==15]

def check(state,p):
    return any(all(state[n-1]==p for n in c) for c in wins)
@lru_cache(None)
def solve(state):
    state=list(state)
    c1=state.count(1); c2=state.count(2)
    if check(state,1): return 1, ()
    if check(state,2): return 2, ()
    if c1+c2==9: return 0, ()
    player = 1 if c1==c2 else 2
    kids=[]
    for i,v in enumerate(state,1):
        if v==0:
            ns=tuple(player if j==i-1 else state[j] for j in range(9))
            out,_=solve(ns)
            kids.append((i,out))
    pref={1:[1,0,2],2:[2,0,1]}[player]
    best=next(o for o in pref if any(out==o for _,out in kids))
    return best, tuple(m for m,o in kids if o==best)

def walk(state=(0,)*9, d=0):
    out, moves = solve(state)
    total=1
    leaves=0
    if not moves:
        return 1,1,d
    player = 1 if sum(v>0 for v in state)%2==0 else 2
    md=d
    for m in moves:
        ns=list(state); ns[m-1]=player
        t,l,dd = walk(tuple(ns), d+1)
        total += t; leaves += l; md=max(md,dd)
    return total, leaves, md
